def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    dangerous_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.30
    if no_water_days >= 2:
        urgency += 0.45
    elif no_water_days >= 1:
        urgency += 0.20
    urgency += scarcity * 0.35
    if day >= 8:
        urgency += 0.08

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.7
        avg_prev = DAILY_SALARY * 0.55

    threat_bid = max(dangerous_bids) if dangerous_bids else highest_prev

    if urgency >= 0.95:
        bid = max(DAILY_SALARY * 0.95, threat_bid + 2.0)
    elif urgency >= 0.65:
        bid = max(DAILY_SALARY * 0.72, min(threat_bid + 1.5, DAILY_SALARY * 1.08))
    elif scarcity >= 0.75:
        bid = max(DAILY_SALARY * 0.52, min(avg_prev + 1.0, DAILY_SALARY * 0.82))
    elif scarcity <= 0.25 and hp > 4 and no_water_days == 0:
        bid = DAILY_SALARY * 0.18
    else:
        bid = max(DAILY_SALARY * 0.32, min(avg_prev * 0.78, DAILY_SALARY * 0.62))

    rich_aggressive = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if pbid is not None and float(pbid) >= DAILY_SALARY * 1.1 and opp.get('budget', 0) > budget:
            rich_aggressive += 1
    if rich_aggressive >= 2 and urgency < 0.65:
        bid *= 0.82

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.9)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Determine how aggressive to be based on yesterday's immediate pressure
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, spend enough to stay safe
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Compute a baseline bid tied to supply relative to requirement.
    # If supply is tight, bid a bit higher; if ample, bid lower.
    supply_ratio = supply / float(WATER_REQ)

    # Conservative strategy: avoid overbidding like Alex (who died after high bids)
    # Scale bid by how tight supply seems.
    if supply_ratio <= 1.0:
        base = DAILY_SALARY * 0.55
    elif supply_ratio <= 1.3:
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.35

    # If yesterday someone bid extremely high, don't chase; stay moderate.
    # Use highest_prev_bid threshold to detect aggressive pressure.
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        # Keep bid below the aggressive level to preserve budget.
        base = min(base, DAILY_SALARY * 0.5)

    # If my HP is low or I'm on water deficit days, increase slightly.
    hp = int(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    if hp <= 2 or no_water_days >= 2:
        base *= 1.25
    elif hp >= 7 and no_water_days == 0:
        base *= 0.9

    # Ensure we don't exceed budget.
    bid = float(min(my_status['budget'], base))

    # Also cap bid to a reasonable fraction of daily salary to avoid reckless spending.
    bid_cap = DAILY_SALARY * 0.65
    if bid > bid_cap:
        bid = bid_cap

    # Final safety: bid at least a small amount if budget allows.
    if my_status['budget'] > 0 and bid <= 0:
        bid = float(min(my_status['budget'], DAILY_SALARY * 0.1))

    return float(bid)

